import { Image } from "expo-image";
import { useTranslation } from "react-i18next";
import { useTheme } from "react-native-paper";

// Generated by design/build-icons.ts from the approved wordmark ("A. Tilde final").
import DARK from "../../assets/images/logo-dark.png";
import LIGHT from "../../assets/images/logo-light.png";

/** Width / height of the generated wordmark PNGs (220 x 40 at 1x). */
const RATIO = 220 / 40;

/** The ChePagame wordmark in the version for the active mode, with an accessible name. */
export function Logo({ width = 220 }: { width?: number }) {
  const { t } = useTranslation();
  const theme = useTheme();
  return (
    <Image
      source={theme.dark ? DARK : LIGHT}
      style={{ width, height: width / RATIO }}
      contentFit="contain"
      accessible
      accessibilityRole="image"
      accessibilityLabel={t("common.appName")}
    />
  );
}
